@@ -11,6 +13,19 @@ import { MissionsService } from '../../api';
 export class MissionList {
   private readonly missionsApi = inject(MissionsService);

+  protected readonly filters: readonly { value: MissionFilter; label: string }[] = [
+    { value: 'all', label: 'All' },
+    { value: 'open', label: 'Open' },
+    { value: 'done', label: 'Done' },
